/* Palette: #1a1a2e (bg), #16213e (card), #0f3460 (accent), #e94560 (highlight), #ffffff (text) */
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #0f3460;
  --highlight: #e94560;
  --text: #ffffff;
  --text-dim: #a0a0b0;
  --border-radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--highlight);
  letter-spacing: 1px;
}

.score-display {
  font-size: 1.25rem;
  font-weight: 600;
  background: var(--accent);
  padding: 6px 16px;
  border-radius: 20px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: #0a0a1a;
  border-radius: 8px;
  overflow: hidden;
  border: 2px solid var(--accent);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(10, 10, 26, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  transition: opacity 0.3s;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  text-align: center;
  max-width: 300px;
}

.overlay-content h2 {
  font-size: 1.5rem;
  margin-bottom: 12px;
  color: var(--highlight);
}

.overlay-content p {
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text-dim);
  margin-bottom: 10px;
}

.controls {
  display: flex;
  gap: 12px;
  margin-top: 20px;
}

.btn {
  flex: 1;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font);
  color: var(--text);
  background: var(--accent);
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, border-color 0.2s;
}

.btn:hover {
  background: var(--highlight);
}

.btn:focus-visible {
  outline: 3px solid var(--highlight);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.hint {
  margin-top: 16px;
  text-align: center;
  font-size: 0.875rem;
  color: var(--text-dim);
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .score-display {
    font-size: 1rem;
    padding: 4px 12px;
  }
  .btn {
    padding: 10px 12px;
    font-size: 0.9rem;
  }
  .hint {
    font-size: 0.8rem;
  }
}

(function() {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayContent = document.getElementById('overlayContent');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID_SIZE = 20;
  const TILE_SIZE = canvas.width / GRID_SIZE;

  const COLORS = {
    bg: '#0a0a1a',
    snake: '#e94560',
    snakeHead: '#ff6b81',
    food: '#0f3460',
    grid: '#16213e'
  };

  let snake, direction, nextDirection, food, score, gameOver, paused, gameLoopId;

  function init() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    food = { x: 15, y: 10 };
    score = 0;
    gameOver = false;
    paused = true;
    updateScore();
    showOverlay('How to Play',
      'Use arrow keys to move the snake.<br>Eat the red food to grow and score points.<br>Avoid hitting walls or yourself.<br><br>Press <strong>Space</strong> or click <strong>Resume</strong> to start.');
    pauseBtn.textContent = 'Resume';
    draw();
  }

  function spawnFood() {
    let newFood;
    do {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
    } while (snake.some(seg => seg.x === newFood.x && seg.y === newFood.y));
    food = newFood;
  }

  function updateScore() {
    scoreEl.textContent = score;
  }

  function showOverlay(title, html) {
    overlayContent.innerHTML = '<h2>' + title + '</h2><p>' + html + '</p>';
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function gameOverScreen() {
    paused = true;
    gameOver = true;
    pauseBtn.textContent = 'Resume';
    showOverlay('Game Over', 'Your score: <strong>' + score + '</strong><br><br>Press <strong>Restart</strong> or <strong>Space</strong> to play again.');
  }

  function step() {
    if (paused || gameOver) return;

    direction = { ...nextDirection };
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
      gameOverScreen();
      return;
    }

    if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
      gameOverScreen();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score++;
      updateScore();
      spawnFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function draw() {
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = COLORS.grid;
    ctx.lineWidth = 1;
    for (let i = 1; i < GRID_SIZE; i++) {
      ctx.beginPath();
      ctx.moveTo(i * TILE_SIZE, 0);
      ctx.lineTo(i * TILE_SIZE, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * TILE_SIZE);
      ctx.lineTo(canvas.width, i * TILE_SIZE);
      ctx.stroke();
    }

    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * TILE_SIZE + 2, food.y * TILE_SIZE + 2, TILE_SIZE - 4, TILE_SIZE - 4);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? COLORS.snakeHead : COLORS.snake;
      ctx.fillRect(seg.x * TILE_SIZE + 1, seg.y * TILE_SIZE + 1, TILE_SIZE - 2, TILE_SIZE - 2);
    });
  }

  function togglePause() {
    if (gameOver) return;
    paused = !paused;
    if (paused) {
      pauseBtn.textContent = 'Resume';
      showOverlay('Paused', 'Press <strong>Space</strong> or click <strong>Resume</strong> to continue.');
    } else {
      pauseBtn.textContent = 'Pause';
      hideOverlay();
    }
  }

  function restart() {
    if (gameLoopId) clearInterval(gameLoopId);
    init();
    gameLoopId = setInterval(step, 150);
  }

  function handleKey(e) {
    const key = e.key;
    if (key === ' ' || key === 'Spacebar') {
      e.preventDefault();
      if (gameOver) {
        restart();
      } else {
        togglePause();
      }
      return;
    }

    if (paused || gameOver) return;

    const dirs = {
      ArrowUp: { x: 0, y: -1 },
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 }
    };

    if (dirs[key]) {
      e.preventDefault();
      const d = dirs[key];
      if (d.x !== -direction.x || d.y !== -direction.y) {
        nextDirection = d;
      }
    }
  }

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);
  window.addEventListener('keydown', handleKey);

  init();
  gameLoopId = setInterval(step, 150);
})();
